func slotPairArmMatches(arm int, name, componentID string, stored SlotIdentity) bool { switch arm { case 1: return componentID != "" && stored.ComponentID != "" && stored.ComponentID == componentID; case 2: return name != "" && stored.Slot != "" && stored.Slot == name; case 3: /* kebab via NormalizeComponentFunction, both sides non-empty */; case 4: return name != "" && ((stored.ComponentFunction != "" && stored.ComponentFunction == name) || (stored.ComponentName != "" && stored.ComponentName == name)) } }
func PairIncomingToStored(name, componentID string, stored []SlotIdentity, consumed func(int) bool) int { for arm := 1; arm <= 4; arm++ { for i := range stored { if consumed(i) { continue }; if slotPairArmMatches(arm, name, componentID, stored[i]) { return i } } }; return -1 }
